import{_ as a,o as d,c as e,a2 as o}from"./chunks/framework.DGvnA5EY.js";const r="/workbuddy-guide/assets/01-meeting-notes.DlzWbjzI.png",b=JSON.parse('{"title":"第 17 章 会议结束不是终点，工作才刚刚开始","description":"> 内容来源：WorkBuddy 官方指南与社区实战案例整理（非官方，© 本指南作者，保留所有权利） 开完会最怕两件事：纪要没人写，决定了没人跟。WorkBuddy 能把\\"录音/记录 → 纪要 → 行动清单 → 跟进提醒\\"这一串自动化掉，让会议的价值落在纸面上、落到人头上。","frontmatter":{"title":"第 17 章 会议结束不是终点，工作才刚刚开始"},"headers":[],"relativePath":"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 17 章 会议结束不是终点，工作才刚刚开始/index.md","filePath":"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 17 章 会议结束不是终点，工作才刚刚开始/index.md","lastUpdated":1791615980000}'),l={name:"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 17 章 会议结束不是终点，工作才刚刚开始/index.md"};function s(n,t,i,h,p,u){return d(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="第-17-章-会议结束不是终点-工作才刚刚开始" tabindex="-1">第 17 章 会议结束不是终点，工作才刚刚开始 <a class="header-anchor" href="#第-17-章-会议结束不是终点-工作才刚刚开始" aria-label="Permalink to &quot;第 17 章 会议结束不是终点，工作才刚刚开始&quot;">​</a></h1><blockquote><p>内容来源：WorkBuddy 官方指南与社区实战案例整理（非官方，© 本指南作者，保留所有权利）</p></blockquote><p>开完会最怕两件事：纪要没人写，决定了没人跟。WorkBuddy 能把&quot;录音/记录 → 纪要 → 行动清单 → 跟进提醒&quot;这一串自动化掉，让会议的价值落在纸面上、落到人头上。</p><p><img src="'+r+`" alt="一只小黑坐在会议桌前，把一堆聊天的气泡收拢成一张写满要点的清单" loading="lazy"></p><p><em>配图为示意插画，用于帮助理解&quot;会议跟进&quot;，与实际软件界面无关。</em></p><h2 id="一、先想清楚-这次会议产出要交付什么" tabindex="-1">一、先想清楚：这次会议产出要交付什么 <a class="header-anchor" href="#一、先想清楚-这次会议产出要交付什么" aria-label="Permalink to &quot;一、先想清楚：这次会议产出要交付什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>要说清什么</th><th>示例</th></tr></thead><tbody><tr><td>目标</td><td>会议要落到什么</td><td>一份纪要 + 可跟进的行动清单</td></tr><tr><td>受众</td><td>谁看</td><td>参会者 + 未参会的领导</td></tr><tr><td>材料</td><td>原始素材</td><td>录音转写/逐字稿/你的速记</td></tr><tr><td>格式</td><td>纪要结构</td><td>背景/要点/结论/待办</td></tr><tr><td>验收</td><td>怎么判断可用</td><td>决议清楚、行动项有负责人和截止</td></tr></tbody></table><h2 id="二、先选对-skill-会议的组合" tabindex="-1">二、先选对 Skill：会议的组合 <a class="header-anchor" href="#二、先选对-skill-会议的组合" aria-label="Permalink to &quot;二、先选对 Skill：会议的组合&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方式 / Skill</th><th>适合处理</th><th>本章怎么用</th><th>注意点</th></tr></thead><tbody><tr><td><strong>腾讯会议 / 会议转写技能</strong></td><td>取转写、取 AI 纪要</td><td>会议到文档一键转</td><td>需要会议平台授权</td></tr><tr><td><strong>通用 Agent（docx）</strong></td><td>出可编辑的 Word 纪要</td><td>排版、修订记录</td><td>见第 11 章</td></tr><tr><td><strong>待办 / 日历连接器</strong></td><td>行动项真正跟进</td><td>到点提醒负责人</td><td>接法见第一篇第 7 章</td></tr><tr><td><strong>腾讯文档</strong></td><td>纪要共享、协作补充</td><td>参会者在线改</td><td>需授权</td></tr><tr><td><strong>find-skills</strong></td><td>找更专业的纪要技能</td><td>如&quot;董事会纪要&quot;模板</td><td>零成本入口</td></tr></tbody></table><h2 id="三、真实可复制提示词" tabindex="-1">三、真实可复制提示词 <a class="header-anchor" href="#三、真实可复制提示词" aria-label="Permalink to &quot;三、真实可复制提示词&quot;">​</a></h2><h3 id="提示词-1-出结构化纪要" tabindex="-1">提示词 1｜出结构化纪要 <a class="header-anchor" href="#提示词-1-出结构化纪要" aria-label="Permalink to &quot;提示词 1｜出结构化纪要&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>根据这份会议记录整理会议纪要，结构为：</span></span>
<span class="line"><span>一、背景与目标；二、讨论要点（分议题）；三、结论与决策；四、遗留问题。</span></span>
<span class="line"><span>只基于记录中的事实，不添加未讨论的内容；敏感的人事/薪酬内容单独标注&quot;待脱敏&quot;。</span></span></code></pre></div><h3 id="提示词-2-抽行动项-谁-做什么-何时" tabindex="-1">提示词 2｜抽行动项（谁/做什么/何时） <a class="header-anchor" href="#提示词-2-抽行动项-谁-做什么-何时" aria-label="Permalink to &quot;提示词 2｜抽行动项（谁/做什么/何时）&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>从纪要里抽出行动清单，每条写清：负责人、事项、截止时间、所需资源。</span></span>
<span class="line"><span>输出为表格；如果记录里没写负责人或时间，标注&quot;待指派&quot;而不是替它编一个。</span></span></code></pre></div><h3 id="提示词-3-脱敏后再喂-机密会议" tabindex="-1">提示词 3｜脱敏后再喂（机密会议） <a class="header-anchor" href="#提示词-3-脱敏后再喂-机密会议" aria-label="Permalink to &quot;提示词 3｜脱敏后再喂（机密会议）&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>这份会议记录涉及未公开决策，请先帮我把公司名、人名、金额替换为【X】，</span></span>
<span class="line"><span>再按提示词 1、2 出纪要和清单。原始敏感信息不要出现在输出里。</span></span></code></pre></div><h2 id="四、执行步骤表" tabindex="-1">四、执行步骤表 <a class="header-anchor" href="#四、执行步骤表" aria-label="Permalink to &quot;四、执行步骤表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>步骤</th><th>WorkBuddy 做什么</th><th>你要确认什么</th></tr></thead><tbody><tr><td>1</td><td>收到录音/逐字稿/速记</td><td>素材完整、机密已脱敏</td></tr><tr><td>2</td><td>出纪要（提示词 1）</td><td>结论/决议准确，没编</td></tr><tr><td>3</td><td>抽行动项（提示词 2）</td><td>负责人/时间真实，没瞎编</td></tr><tr><td>4</td><td>接待办/日历，设提醒</td><td>行动项真能跟进</td></tr></tbody></table><h2 id="五、让行动项真正-跟起来" tabindex="-1">五、让行动项真正&quot;跟起来&quot; <a class="header-anchor" href="#五、让行动项真正-跟起来" aria-label="Permalink to &quot;五、让行动项真正&quot;跟起来&quot;&quot;">​</a></h2><p>纪要和行动清单出了，不等于跟进了。把清单里的待办，<strong>接上你的待办/日历</strong> （连接器，见第一篇第 7 章），到点提醒负责人——这才是&quot;会议之后&quot;的闭环。也可配合 第一篇第 10 章自动化，每周一把未关闭的行动项汇总推送给你。</p><h2 id="六、零成本-skill-把-会议纪要-固化" tabindex="-1">六、零成本 Skill：把&quot;会议纪要&quot;固化 <a class="header-anchor" href="#六、零成本-skill-把-会议纪要-固化" aria-label="Permalink to &quot;六、零成本 Skill：把&quot;会议纪要&quot;固化&quot;">​</a></h2><p>跑顺提示词 1、2 后，用 <code>skill-creator</code> 固化成&quot;会议纪要&quot;技能：以后丢一份记录， 自动出结构纪要 + 行动清单，格式固定、不用每次重写。</p><h2 id="七、实际效果与验收标准" tabindex="-1">七、实际效果与验收标准 <a class="header-anchor" href="#七、实际效果与验收标准" aria-label="Permalink to &quot;七、实际效果与验收标准&quot;">​</a></h2><p><strong>实际效果</strong>：会议一结束，一份干净纪要和一张责任到人的行动清单就躺在共享文档里。</p><p><strong>验收标准</strong>：</p><ul><li>[ ] 纪要的决议/结论与记录一致，没有添加未讨论内容</li><li>[ ] 行动项有真实负责人和截止时间（缺失的标&quot;待指派&quot;，没被编出）</li><li>[ ] 机密会议已脱敏，敏感信息未泄露</li><li>[ ] 行动项已接待办/日历，能跟进</li></ul><h2 id="八、一个必须记住的坑" tabindex="-1">八、一个必须记住的坑 <a class="header-anchor" href="#八、一个必须记住的坑" aria-label="Permalink to &quot;八、一个必须记住的坑&quot;">​</a></h2><p><strong>会议内容可能含机密</strong>，上传前想清楚：这份记录要不要进 AI、存哪。涉及薪酬、人事、 未公开决策的，宁可手动脱敏再喂，或只在本地工作区处理（第一篇第 3、12 章讲的 工作区隔离同样适用）。</p><h2 id="小白说明书" tabindex="-1">小白说明书 <a class="header-anchor" href="#小白说明书" aria-label="Permalink to &quot;小白说明书&quot;">​</a></h2><blockquote><p><strong>逐字稿</strong>：把语音一字不差转成的文字稿，是 AI 整理纪要的原材料。</p><p><strong>行动项（Action Item）</strong>：会议上定的&quot;谁、做什么、何时完成&quot;的具体任务。</p><p><strong>闭环</strong>：从开会、记录、派活到提醒跟进，整条不断链，才叫闭环。</p><p><strong>零成本 Skill</strong>：用 skill-creator 把周常纪要固化成专属技能。</p></blockquote><h2 id="本章任务清单" tabindex="-1">本章任务清单 <a class="header-anchor" href="#本章任务清单" aria-label="Permalink to &quot;本章任务清单&quot;">​</a></h2><ul><li>[ ] 拿一次真实会议记录，让 AI 出纪要 + 行动清单</li><li>[ ] 核对行动清单的负责人/时间是否准确（缺失的是否标&quot;待指派&quot;）</li><li>[ ] 想清楚：机密会议记录以后怎么安全处理</li><li>[ ] （进阶）用 skill-creator 把&quot;会议纪要&quot;固化成技能</li></ul><hr><p><em>下一篇：第 18 章——把投资分析变成你的日常。</em></p><hr><p><em>本指南为第三方非官方整理，版权归作者所有，转载请注明出处。</em></p>`,36)])])}const q=a(l,[["render",s]]);export{b as __pageData,q as default};
